// Single source of truth for every published component in @arshad-shah/cynosure-react.
//
// Adding a new component is one row here plus a docs page; the rest is derived:
//   • `packages/react/tsup.config.ts` reads `componentEntries()` for its build map.
//   • `packages/react/package.json` exports + files arrays are regenerated by
//     `scripts/sync-component-subpaths.mjs` (runs in `prebuild`).
//   • Per-component proxy dirs (`packages/react/<slug>/package.json`) are
//     regenerated by the same script.
//   • `packages/docs/src/lib/components-manifest.ts` re-exports doc slugs.
//   • `packages/docs/astro.config.mjs` groups items by `sidebarGroup`.
//
// Slug conventions:
//   • `slug`  — kebab-case, the subpath in `@arshad-shah/cynosure-react/<slug>`
//               and the docs page slug `components/<slug>`.
//   • `entry` — basename of the dist file (`dist/<entry>.js`). Some legacy
//               entries jam together as one word (e.g. `iconbutton`); newer
//               entries match `slug`. Always preserve the existing value so
//               consumers' deep imports keep working.
//
// `sidebarGroup` controls placement in the docs sidebar. Components with
// `sidebarGroup: null` (currently every layout primitive) don't appear in the
// sidebar — they're introduced via the Foundations pages instead.

/** @typedef {'layout' | 'typography' | 'forms' | 'overlay' | 'navigation' | 'data-display' | 'feedback'} Category */
/** @typedef {'Typography' | 'Buttons' | 'Forms' | 'Feedback' | 'Overlays' | 'Navigation' | 'Data display'} SidebarGroup */
/**
 * @typedef {Object} ComponentEntry
 * @property {string} name           PascalCase identifier matching the source folder + export.
 * @property {string} slug           Subpath / docs-page slug (kebab-case).
 * @property {string} entry          Dist-file basename (`dist/<entry>.js`).
 * @property {Category} category     Source directory + default sidebar group.
 * @property {SidebarGroup | null} [sidebarGroup]  Override the sidebar bucket. `null` → not in sidebar.
 * @property {string} [sidebarLabel] Override the sidebar label (defaults to `name`).
 * @property {string} [sidebarBadge] Sidebar badge text (e.g. `'beta'`).
 * @property {string} [sourcePath]   Override the source entry (relative to `packages/react/`). Defaults to `src/<dir>/<name>/index.ts`.
 */

/** Sidebar group order — matches the docs sidebar top-to-bottom. */
export const SIDEBAR_GROUPS = /** @type {const} */ ([
  'Layout',
  'Typography',
  'Buttons',
  'Forms',
  'Feedback',
  'Overlays',
  'Navigation',
  'Data display',
]);

/** Maps each category to its source directory under `packages/react/src/`. */
const CATEGORY_DIR = /** @type {const} */ ({
  layout: 'primitives/layout',
  typography: 'typography',
  forms: 'forms',
  overlay: 'overlay',
  navigation: 'navigation',
  'data-display': 'data-display',
  feedback: 'feedback',
});

/** Default sidebar group per category. `null` skips the sidebar. */
const DEFAULT_SIDEBAR_GROUP = /** @type {const} */ ({
  layout: 'Layout',
  typography: 'Typography',
  forms: 'Forms',
  overlay: 'Overlays',
  navigation: 'Navigation',
  'data-display': 'Data display',
  feedback: 'Feedback',
});

