/* ── Derived helpers ──────────────────────────────────────────────── */

/**
 * Components in the given source category, in manifest order.
 * @param {Category} category
 */
export function componentsByCategory(category) {
  return COMPONENTS.filter((c) => c.category === category);
}

/**
 * Resolve the effective sidebar group for a component. Falls back to the
 * category default; returns `null` when the component is excluded from the
 * sidebar.
 * @param {ComponentEntry} c
 */
export function sidebarGroupFor(c) {
  return c.sidebarGroup ?? DEFAULT_SIDEBAR_GROUP[c.category];
}

/**
 * Group the manifest by sidebar bucket and return entries in manifest order.
 * @returns {Record<SidebarGroup, ComponentEntry[]>}
 */
export function componentsBySidebarGroup() {
  const out = /** @type {Record<SidebarGroup, ComponentEntry[]>} */ (
    Object.fromEntries(SIDEBAR_GROUPS.map((g) => [g, []]))
  );
  for (const c of COMPONENTS) {
    const group = sidebarGroupFor(c);
    if (group) out[group].push(c);
  }
  return out;
}

/**
 * Resolve the source-file entry for a component, relative to
 * `packages/react/`.
 * @param {ComponentEntry} c
 */
export function sourceEntryFor(c) {
  return c.sourcePath ?? `src/${CATEGORY_DIR[c.category]}/${c.name}/index.ts`;
}

/**
 * tsup `entry` map keyed by dist-file basename → source path.
 * Caller composes this with the static non-component entries.
 * @returns {Record<string, string>}
 */
export function componentEntries() {
  /** @type {Record<string, string>} */
  const out = {};
  for (const c of COMPONENTS) out[c.entry] = sourceEntryFor(c);
  return out;
}

/** Every published subpath slug (`./<slug>` exports). */
export const COMPONENT_SLUGS = COMPONENTS.map((c) => c.slug);

/**
 * Slugs that ship a docs page under `src/content/docs/components/<slug>`.
 * Every manifest entry has a page — layout primitives included — so the
 * sidebar surfaces the full inventory.
 */
export const DOC_COMPONENT_SLUGS = COMPONENTS.map((c) => c.slug);
